// CellSetReset restores CellSet's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func CellSetReset(value *CellSet) {
	for i := range value.Cells {
		CellReset(&value.Cells[i])
	}
	value.CellsCount = 0
}

func CellSetMeasureBody(value *CellSet, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !CellSetSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func CellSetSaveBody(w *TableWriter, value *CellSet) bool {
	if !CellSetSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func CellSetSaveBodyFields(w *TableWriter, value *CellSet) bool {
	{
		if value.CellsCount < 0 || value.CellsCount > 64 {
			return false
		}
		if value.CellsCount > 0 {
			if ref := w.Ids.refAtHit(12, 0x0c99365e92f7d2f2); !w.headerPair(ref, 14) {
				w.headerRest(ref, 14)
			}
			if value.CellsCount < 0 || value.CellsCount > 64 {
				return false
			}
			{
				mark := w.Ids.Count
				payload18 := TableWriter{Measuring: true, Ids: w.Ids}
				pairs := uint64(0)
				for i := 0; i < int(value.CellsCount); i++ {
					{
						mark := payload18.Ids.Count
						n := CellMeasureBody(&value.Cells[i], payload18.Ids)
						if n < 0 {
							return false
						}
						if !payload18.putLebPair(uint64(n)) {
							payload18.putLebWide(uint64(n))
						}
						if payload18.Measuring {
							payload18.Advance(n)
						} else {
							payload18.Ids.Truncate(mark)
							if !CellSaveBody(&payload18, &value.Cells[i]) {
								return false
							}
						}
					}
					pairs++
				}
				if payload18.Overflow {
					return false
				}
				n := int64(1) + tableLebBytes(pairs) + payload18.Offset
				if !w.putLebPair(uint64(n)) {
					w.putLebWide(uint64(n))
				}
				if w.Measuring {
					w.Advance(n)
				} else {
					w.Ids.Truncate(mark)
					w.Put8(13)
					if !w.putLebPair(pairs) {
						w.putLebWide(pairs)
					}
					for i := 0; i < int(value.CellsCount); i++ {
						{
							mark := w.Ids.Count
							n := CellMeasureBody(&value.Cells[i], w.Ids)
							if n < 0 {
								return false
							}
							if !w.putLebPair(uint64(n)) {
								w.putLebWide(uint64(n))
							}
							if w.Measuring {
								w.Advance(n)
							} else {
								w.Ids.Truncate(mark)
								if !CellSaveBody(w, &value.Cells[i]) {
									return false
								}
							}
						}
					}
				}
			}
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func CellSetLoadBody(r *TableReader, value *CellSet) bool {
	CellSetReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0x0c99365e92f7d2f2: // cells
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
				} else {
					if elemKind != 13 {
						r.Report.KindMismatch++
						break
					}
					keep := count
					if keep > 64 {
						keep = 64
						r.Report.Clamped++
					}
					previous := value.CellsCount
					decoded := int32(0)
					for i := uint64(0); i < keep; i++ {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						CellLoadBody(&elem, &value.Cells[i])
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							CellReset(&value.Cells[i])
						}
						decoded = int32(i + 1)
					}
					for i := decoded; i < previous; i++ {
						CellReset(&value.Cells[i])
					}
					value.CellsCount = decoded
				}
			}
			r.Take(sub)
			if r.Nodes.Carve.Refused {
				return false
			}
		case 0xffffffffffffffff:
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

