func StreamTransitionLoadBodyRetain(r *TableRetainReader, value *StreamTransition) bool {
	StreamTransitionReset(value)
	r.Retain.discard(r.Path, false, 0)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		switch fieldID {
		case 0xee63aaad45b1b116: // state
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.State[:])
				value.StateLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 32 {
				keep = tableUtf8Clamp(sub.Buffer, 32)
				r.Report.Clamped++
			}
			clear(value.State[:])
			copy(value.State[:keep], sub.Buffer)
			value.StateLength = int32(keep)
		case 0xb733af3b0d745380: // cause
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Cause[:])
				value.CauseLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 300 {
				keep = tableUtf8Clamp(sub.Buffer, 300)
				r.Report.Clamped++
			}
			clear(value.Cause[:])
			copy(value.Cause[:keep], sub.Buffer)
			value.CauseLength = int32(keep)
		case 0xeac9afef1a00b5e8: // waiting
			if kind != 4 {
				if tableKindWidens(kind, 4) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := r.Signed(kind)
						value.Waiting = int32(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(4) {
				r.Report.Malformed = true
				return false
			}
			{
				v := int32(r.Get32())
				value.Waiting = int32(v)
			}
		case 0x9746d619fd1fc965: // owners
			if kind != 14 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if len(sub.Buffer) >= 2 {
				header := sub
				header.Buffer = r.Buffer[r.Offset-int64(len(sub.Buffer)):]
				elemKind := header.Get8()
				count, ok := header.Leb()
				sub.Offset = header.Offset
				if !ok {
					r.Report.Malformed = true
				} else {
					if elemKind != 13 {
						r.Report.KindMismatch++
						break
					}
					r.Retain.discard(r.Path, true, 3)
					keep := count
					if keep > 16 {
						keep = 16
						r.Report.Clamped++
					}
					previous := value.OwnersCount
					decoded := int32(0)
					for i := uint64(0); i < keep; i++ {
						elem, ok := sub.Body()
						if !ok {
							r.Report.Malformed = true
							break
						}
						elem.Path = r.Path.step(3, uint32(i))
						Name128LoadBodyRetain(&elem, &value.Owners[i])
						sub.Take(elem)
						if sub.Nodes.Carve.Refused {
							r.Nodes.Carve = sub.Nodes.Carve
							return false
						}
						if elem.Offset != int64(len(elem.Buffer)) {
							r.Report.Malformed = true
							Name128Reset(&value.Owners[i])
						}
						decoded = int32(i + 1)
					}
					for i := decoded; i < previous; i++ {
						Name128Reset(&value.Owners[i])
					}
					value.OwnersCount = decoded
				}
			}
			r.Take(sub)
			if r.Nodes.Carve.Refused {
				return false
			}
		default:
			r.Report.Unknown++
			if !r.capture(fieldID, kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

// DecisionDeliveryReset restores DecisionDelivery's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func DecisionDeliveryReset(value *DecisionDelivery) {
	clear(value.Lane[:])
	value.LaneLength = 0
	clear(value.To[:])
	value.ToLength = 0
	clear(value.From[:])
	value.FromLength = 0
	clear(value.Set[:])
	value.SetLength = 0
	clear(value.Body[:])
	value.BodyLength = 0
	clear(value.Token[:])
	value.TokenLength = 0
	value.PreparedAt = 0
	value.RetryBefore = 0
	value.SentAt = 0
	clear(value.Fault[:])
	value.FaultLength = 0
	for i := range value.Reports {
		Name256Reset(&value.Reports[i])
	}
	value.ReportsCount = 0
	value.UnknownReceipts = 0
}

