func NoteLoadRetain(region, wire []byte, retain *TableRetain, report *TableReport) *Note {
	return (*Note)(tableRegionLoadRetain(region, wire, NoteTableType(), NoteTableType().NodeType, 0, report, retain))
}
func NoteMeasureRetain(value *Note, retain *TableRetain, allocator ...TableAllocator) int64 {
	return tableRegionSaveRetain(unsafe.Pointer(value), NoteTableType(), nil, true, retain, nil, allocator...)
}
func NoteSaveRetain(value *Note, retain *TableRetain, buffer []byte, report *TableReport, allocator ...TableAllocator) int64 {
	if report == nil {
		return -1
	}
	return tableRegionSaveRetain(unsafe.Pointer(value), NoteTableType(), buffer, false, retain, report, allocator...)
}
func NoteMeasureBodyRetain(value *Note, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !NoteSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func NoteSaveBodyRetain(w *TableRetainWriter, value *Note) bool {
	if !NoteSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
