func SeatChangeMeasureBodyRetain(value *SeatChange, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !SeatChangeSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func SeatChangeSaveBodyRetain(w *TableRetainWriter, value *SeatChange) bool {
	if !SeatChangeSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
